import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.aJDz64y9.js";const m=JSON.parse('{"title":"Реализация на FiveM","description":"","frontmatter":{},"headers":[],"relativePath":"crime/implementation.md","filePath":"crime/implementation.md","lastUpdated":1794540927000}'),o={name:"crime/implementation.md"};function n(i,t,l,s,c,h){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="реализация-на-fivem" tabindex="-1">Реализация на FiveM <a class="header-anchor" href="#реализация-на-fivem" aria-label="Permalink to &quot;Реализация на FiveM&quot;">​</a></h1><p>Всё описанное делается штатными средствами FiveM. Сложность не в отдельных механиках, а в том, чтобы сервер оставался единственным источником правды.</p><h2 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to &quot;Архитектура&quot;">​</a></h2><ul><li><strong>Ядро и три активности.</strong> Один общий ресурс держит «дело» как конечный автомат на сервере, тревогу объектов, жар районов, улики, реестр краденого и цены скупки. Дома, магазины и угон — отдельные ресурсы поверх ядра.</li><li><strong>Содержимое в данных.</strong> Точки, ступени, таблицы добычи и цены лежат в конфигах, которые геймдизайнер правит без программиста.</li><li><strong>vRP.</strong> Деньги, инвентарь, группы и права идут через штатные интерфейсы vRP: Proxy между ресурсами, Tunnel между сервером и клиентом. Роли механика, полицейского и мастера — группы и права. Рост навыков ложится на aptitudes: право вида <code>!aptitude.crime.lockpick.&gt;2</code> открывает инструмент или ступень.</li><li><strong>Краденое в инвентаре vRP.</strong> Инвентарь хранит пары «идентификатор — количество», поэтому серийник и номер дела кодируются параметрическим предметом вида <code>stolen_tv|A1B2C3</code> либо лежат в отдельной таблице-реестре. Тайники и багажники — штатные сундуки. Форматы взяты из <a href="https://vrp-framework.github.io/vRP/dev/index.html" target="_blank" rel="noreferrer">документации vRP 2</a>; на старой версии или доработанном инвентаре детали будут другими.</li><li><strong>Чужие библиотеки — с оглядкой.</strong> Популярный стек ox заархивирован, <a href="https://github.com/CommunityOx/ox_inventory" target="_blank" rel="noreferrer">репозиторий ox_inventory закрыт 28 апреля 2026</a>. Опираться стоит на то, что у вас уже стоит и поддерживается.</li></ul><h2 id="что-и-как-кодить" tabindex="-1">Что и как кодить <a class="header-anchor" href="#что-и-как-кодить" aria-label="Permalink to &quot;Что и как кодить&quot;">​</a></h2><p>Объём — грубая оценка для одного программиста: S — до недели, M — 1–3 недели, L — месяц и больше.</p><table tabindex="0"><thead><tr><th>Механика</th><th>Как делается</th><th>Объём</th><th>Подводные камни</th></tr></thead><tbody><tr><td>Мини-игры: замок, проводка, сканер, VIN</td><td>Окно NUI. Сервер выдаёт параметры и одноразовый токен, проверяет минимальное время</td><td>S</td><td>Ответ клиента «прошёл» не доказательство: сервер сверяет дистанцию, инструмент и фазу дела</td></tr><tr><td>Шкала шума</td><td>Клиент считает шум от скорости и стойки; шум от действий начисляет сервер</td><td>M</td><td>Клиентскую часть можно занизить читом, нужны потолки и сверка с действиями</td></tr><tr><td>Голос в шуме и запугивании</td><td>Клиент знает, говорит ли игрок и в каком режиме дальности</td><td>S–M</td><td>Зависит от вашего голосового ресурса; порог калибруется на тестах</td></tr><tr><td>Интерьеры домов</td><td>Дома на «шеллах»: шелл на своих координатах под домом, вход телепортом. Дома на MLO: двери через ваш ресурс замков, без телепорта</td><td>M</td><td><a href="https://docs.fivem.net/docs/scripting-reference/onesync/" target="_blank" rel="noreferrer">Документация OneSync</a> не относит интерьеры к сценариям routing buckets и советует conceal-нативы. При уникальных координатах инстансы не нужны: команда, полиция и жилец видят друг друга сами. В MLO взлом и свет фонарей видны с улицы без доработок</td></tr><tr><td>Обыск и добыча</td><td>Сервер генерирует содержимое точек при открытии дела; клиент знает только, где можно искать</td><td>S–M</td><td>Не отправлять клиенту таблицу добычи заранее</td></tr><tr><td>Перенос крупных вещей</td><td>Проп крепится к персонажу; «несёт такую-то вещь» хранится в state bag игрока, остальные клиенты рисуют проп локально</td><td>S–M</td><td>Не создавать сетевой объект на каждую вещь. Перенос вдвоём — отдельная задача класса L, отложить</td></tr><tr><td>Жильцы-NPC</td><td>Сначала таймер и звуки: шаги, свет, лай. Потом пед с простым поведением</td><td>M–L</td><td>Поведение педов в интерьерах капризно, владение педом переходит между клиентами</td></tr><tr><td>Полки магазинов</td><td>Зоны взаимодействия на секциях, остаток хранит сервер</td><td>S без визуала, M–L с пустеющими полками</td><td>Ванильные полки — часть интерьера. Пустеющие полки требуют маппера: свои модели или подмена пропов. Проверить прототипом</td></tr><tr><td>Щиток, рольставни, свет</td><td>Состояние объекта на сервере. Двери — через ваш ресурс замков. Свет гасится у клиентов, которые находятся внутри</td><td>M</td><td>Как именно гаснет свет, зависит от интерьера. Проверить прототипом на двух-трёх магазинах</td></tr><tr><td>Жучки, розыск, считыватель номеров</td><td>Серверный цикл раз в 20–30 секунд шлёт координаты машин с жучком в диспетчерскую. Номера рядом с патрулём сверяются со списком розыска</td><td>S–M</td><td>Состояние угнанной машины хранить в базе, чтобы она пережила рестарт</td></tr><tr><td>Услуги СТО</td><td>Зона подъёмника, взаимодействие с частями машины для сканера и разбора. Качество перебивки — поле в базе машин</td><td>M</td><td>Привязка к вашим ресурсам механиков и ключей</td></tr><tr><td>Машины под заказ и рейсы порта</td><td>Сервер создаёт машину на точке, ведёт расписание окон и считает цену</td><td>M</td><td>Серверное создание сущностей и режим entity lockdown настраиваются вместе</td></tr><tr><td>Улики: камеры, отпечатки, серийники</td><td>Записи в базе по делу. Камера хранит приметы на момент преступления</td><td>M</td><td>Видеозаписи не будет: только приметы и просмотр «вживую». Полиции нужен интерфейс дел</td></tr><tr><td>Дома и машины игроков</td><td>Интеграция с вашими системами жилья и гаражей плюс новая страховка</td><td>L</td><td>Самая рискованная часть по балансу, делать последней</td></tr></tbody></table><h2 id="защита-от-читов" tabindex="-1">Защита от читов <a class="header-anchor" href="#защита-от-читов" aria-label="Permalink to &quot;Защита от читов&quot;">​</a></h2><p>Клиент считается скомпрометированным: любое клиентское событие чит может вызвать сам.</p><ul><li><strong>Клиент просит, сервер решает.</strong> Событий вида «выдай предмет» нет. На каждое действие сервер проверяет дистанцию до объекта, фазу дела, наличие инструмента и минимальное время.</li><li><strong>State bags.</strong> По умолчанию клиент может писать состояние своего игрока и своих сущностей. Переменная <code>sv_stateBagStrictMode true</code> оставляет запись только серверу (<a href="https://docs.fivem.net/docs/scripting-manual/networking/state-bags/" target="_blank" rel="noreferrer">документация</a>).</li><li><strong>Сущности.</strong> Режим entity lockdown <code>strict</code> или <code>relaxed</code> запрещает клиентам создавать сущности. Нужные машины создаёт сервер через <code>CreateVehicleServerSetter</code>, а <code>SetEntityOrphanMode</code> не даёт им исчезнуть.</li><li><strong>Частота и аномалии.</strong> Сервер ограничивает частоту запросов и пишет в журнал слишком быстрые мини-игры, добычу вне фазы и прыжки между точками.</li><li><strong>Логи экономики.</strong> Каждая выдача и продажа пишется с номером дела. Без этого не посчитать метрики и не найти конвейер.</li></ul><p>Имена нативов приведены как ориентир для программиста; точные сигнатуры — в <a href="https://docs.fivem.net/natives/" target="_blank" rel="noreferrer">справочнике нативов</a>.</p>',11)])])}const p=d(o,[["render",n]]);export{m as __pageData,p as default};
